"""Bypass nodes and groups by plain-text or regular-expression rules."""

from __future__ import annotations

import re


class QQIgnoreRules:
    CATEGORY = "QQ/工具"
    FUNCTION = "describe"
    RETURN_TYPES = ("STRING",)
    RETURN_NAMES = ("状态",)
    OUTPUT_NODE = True
    DESCRIPTION = (
        "用文字或正则匹配节点标题、组名，把匹配到的节点设为「绕过(Bypass)」。"
        "规则前加 ! 表示排除，即使被其它规则命中也不会被绕过。"
    )

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "启用": ("BOOLEAN", {"default": False, "label_on": "启用", "label_off": "关闭"}),
                "节点": ("STRING", {
                    "default": "",
                    "tooltip": (
                        "单行，多项用逗号分隔。普通文字按包含匹配；含 ^ $ * | 等符号时按正则。"
                        "前加 ! 表示排除，例如：^Get_图片, !Get_图片 1"
                    ),
                }),
                "组": ("STRING", {
                    "default": "",
                    "tooltip": (
                        "单行，多项用逗号分隔。匹配组名，组内全部节点会被绕过。支持正则。"
                        "前加 ! 表示该组不被绕过，例如：^预处理, !保留组"
                    ),
                }),
            }
        }

    @staticmethod
    def describe(启用, 节点, 组):
        state = "启用" if 启用 else "关闭"
        return (f"[{state}] 节点={节点} 组={组}",)


def split_rules(text):
    return [part.strip() for part in re.split(r"[,，;；\n]+", str(text or "")) if part.strip()]


def is_exclusion(rule):
    return str(rule or "").strip().startswith("!")


def strip_exclusion(rule):
    text = str(rule or "").strip()
    return text[1:].strip() if text.startswith("!") else text


def split_include_exclude(text):
    """把规则文本拆成 (命中列表, 排除列表)。"""
    include, exclude = [], []
    for item in split_rules(text):
        (exclude if is_exclusion(item) else include).append(strip_exclusion(item))
    return [r for r in include if r], [r for r in exclude if r]


def rule_matches(rule, value):
    text = str(value or "")
    pattern = str(rule or "").strip()
    if not pattern or not text:
        return False
    if re.search(r"[\\^$.*+?()[\]{}|]", pattern):
        try:
            return re.search(pattern, text) is not None
        except re.error:
            return False
    return pattern in text


def any_rule_matches(rules, values):
    return any(rule_matches(rule, value) for rule in rules for value in values)


NODE_CLASS_MAPPINGS = {"QQIgnoreRules": QQIgnoreRules}
NODE_DISPLAY_NAME_MAPPINGS = {"QQIgnoreRules": "QQ-绕过规则"}
